\includegraphics[width=0.95\textwidth]{figures/fig_concept_overview.pdf}
\caption{Metric-induced layer selection reversal. The same hidden states, evaluated with different layer selection metrics, yield opposite conclusions about the HS advantage. Crossing-rate composite selects shallow layers (L0--L2), where HS and text probes perform equivalently ($p{=}0.83$); threshold-based metrics select deep layers (L14--L63), where HS probes significantly outperform text (+20pp, $p{<}0.005$). The 14--61 layer gap arises from the metric alone.}
\label{fig:concept_overview}
\end{figure*}

